SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  in
 - output out

Implement the following Moore state machine with two states, one input,
and one output. The reset state is B and reset is active-high
synchronous.

  B (out=1) --in=0--> A
  B (out=1) --in=1--> B
  A (out=0) --in=0--> B
  A (out=0) --in=1--> A



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire in,
    output reg  out
);

    // State encoding for a Moore machine with two states: A and B
    // State B has out = 1, State A has out = 0.
    // Reset state is B.
    localparam STATE_B = 1'b0;
    localparam STATE_A = 1'b1;

    reg current_state, next_state;

    // State register with active-high synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            current_state <= STATE_B;
        end else begin
            current_state <= next_state;
        end
    end

    // Next-state logic
    always @(*) begin
        case (current_state)
            STATE_B: begin
                if (in == 1'b0)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end

            STATE_A: begin
                if (in == 1'b0)
                    next_state = STATE_B;
                else
                    next_state = STATE_A;
            end

            default: begin
                next_state = STATE_B;
            end
        endcase
    end

    // Output logic (Moore outputs depend only on the current state)
    always @(*) begin
        case (current_state)
            STATE_B: out = 1'b1;
            STATE_A: out = 1'b0;
            default: out = 1'b1;
        endcase
    end

endmodule
```

